/**
 * Session 140 — Curated knowledge seed (part 1: core builders, concepts,
 * instructions, explanations, policy records).
 *
 * Every record is REAL, curated educational content with a confidence
 * classification and sources. The catalog never pretends to know everything:
 * records it does not hold are answered with an honest "insufficient
 * knowledge" response. Fast-changing facts (prices, elections, scores) are
 * deliberately NOT seeded — they belong to the dynamic layer where they must
 * carry SOURCE + DATE + VERIFICATION STATUS + LAST UPDATED.
 */
import type {
  KnowledgeConfidence,
  KnowledgeMisconception,
  KnowledgeRecord,
  KnowledgeReference,
} from "@windels/shared";

/** Date every catalog record was authored/verified into the catalog. */
export const KNOWLEDGE_SEED_DATE = "2026-08-08";

const SRC_BRITANNICA: KnowledgeReference = { label: "Encyclopaedia Britannica", url: "https://www.britannica.com" };
const SRC_UN: KnowledgeReference = { label: "United Nations", url: "https://www.un.org" };
const SRC_WHO: KnowledgeReference = { label: "World Health Organization", url: "https://www.who.int" };
const SRC_NASA: KnowledgeReference = { label: "NASA", url: "https://www.nasa.gov" };
const SRC_NOBEL: KnowledgeReference = { label: "The Nobel Prize organization", url: "https://www.nobelprize.org" };
const SRC_HISTORY: KnowledgeReference = { label: "US National Archives", url: "https://www.archives.gov" };

interface RecordInput {
  id: string;
  title: string;
  aliases?: string[];
  question: string;
  categoryIds: string[];
  summary: string;
  sections: Partial<Record<string, string>>;
  examples?: string[];
  misconceptions?: KnowledgeMisconception[];
  relatedIds?: string[];
  sources?: KnowledgeReference[];
  confidence?: KnowledgeConfidence;
  verificationNote?: string;
  professionalAssistanceNote?: string;
  criteria?: KnowledgeRecord["criteria"];
}

function build(kind: KnowledgeRecord["kind"], tier: KnowledgeRecord["tier"], intents: KnowledgeRecord["intents"], input: RecordInput): KnowledgeRecord {
  return {
    id: input.id,
    kind,
    categoryIds: input.categoryIds,
    title: input.title,
    aliases: input.aliases ?? [],
    question: input.question,
    intents,
    tier,
    confidence: input.confidence ?? "well_supported",
    provenance: "catalog",
    summary: input.summary,
    sections: input.sections,
    examples: input.examples,
    misconceptions: input.misconceptions,
    steps: undefined,
    criteria: input.criteria,
    relatedIds: input.relatedIds,
    sources: input.sources,
    lastUpdated: KNOWLEDGE_SEED_DATE,
    verificationNote: input.verificationNote,
    professionalAssistanceNote: input.professionalAssistanceNote,
  };
}

const concept = (input: RecordInput): KnowledgeRecord =>
  build("concept", "stable", ["definition", "explanation"], input);

const instruction = (input: RecordInput): KnowledgeRecord =>
  build("instruction", "stable", ["instruction", "personal_guidance"], input);

const explanation = (input: RecordInput): KnowledgeRecord =>
  build("explanation", "stable", ["explanation", "definition"], input);

const policy = (input: RecordInput): KnowledgeRecord =>
  build("policy", "stable", ["definition", "research"], input);

